+/*
+ * Copyright (c) Huawei Technologies Co., Ltd. 2025-2025. All rights reserved.
+ */
+
+package com.huawei.oss.wireless.experienceassuranceservice.common.impl.utils;
+
+import com.huawei.bsp.log.OssLog;
+import com.huawei.bsp.log.OssLogFactory;
+import com.huawei.bsp.remoteservice.exception.ServiceException;
+import com.huawei.maos.commons.deploy.EnvUtil;
+import com.huawei.maos.commons.text.StringUtil;
+import com.huawei.oss.rest.util.RestCaller;
+import com.huawei.oss.rest.util.RestMethod;
+
+import java.util.ArrayList;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Map;
+import java.util.Optional;
+import java.util.stream.Collectors;
+
+/**
+ * 实例工具类，用于查询微服务的所有实例ID和当前实例ID
+ *
+ * @since 2025/10/18
+ */
+public class InstanceUtils {
+    private static final OssLog LOGGER = OssLogFactory.getLogger(InstanceUtils.class);
+
+    private static final String INSTANCE_ONLY_POLICY = "instanceOnly";
+
+    private static final String BACKEND_LIST_POLICY_HEADER = "XX-Backend-List-Policy";
+
+    private static final String BACKEND_LIST_HEADER = "Xx-Backend-List";
+
+    private static final String ALL_INSTANCES_PREFIX = "all=";
+
+    private static final String POD_NAME_ENV = "POD_NAME";
+
+    private static final String INSTANCE_ID_SEPARATOR = ",";
+
+    private static final String INSTANCE_NAME_SEPARATOR = "-";
+
+    /**
+     * 此处使用任意本服务的接口都可以，请求头中的XX-Backend-List-Policy为instanceOnly时仅返回本服务的所有实例信息，并不会执行接口
+     */
+    private static final String POLICY_URL = "/rest/oss/inner/experienceassurance/v1/policy";
+
+    /**
+     * 查询所有实例ID
+     *
+     * @return 所有实例ID列表
+     */
+    public static List<Integer> queryAllInstanceIds() {
+        List<Integer> instanceIds = new ArrayList<>();
+        try {
+            LOGGER.info("Start to query all instance IDs.");
+
+            // 调用IR接口获取所有实例ID 并 从响应头中获取实例列表
+            Map<String, String> respHeaderMap = new RestCaller.Builder(POLICY_URL, RestMethod.POST)
+                .header(BACKEND_LIST_POLICY_HEADER, INSTANCE_ONLY_POLICY).build().call().getRespHeaderMap();
+
+            String backendList = getBackendList(respHeaderMap);
+            if (!StringUtil.isEmpty(backendList) && backendList.startsWith(ALL_INSTANCES_PREFIX)) {
+                String allInstances = backendList.substring(ALL_INSTANCES_PREFIX.length());
+                String[] instances = allInstances.split(INSTANCE_ID_SEPARATOR);
+
+                // 使用流式风格解析每个实例ID并过滤掉空值
+                instanceIds = Arrays.stream(instances)
+                    .map(InstanceUtils::parseInstanceId)
+                    .filter(Optional::isPresent)
+                    .map(Optional::get)
+                    .collect(Collectors.toList());
+            }
+
+            LOGGER.info("Query all instance IDs successfully, instance count: {}", instanceIds.size());
+        } catch (ServiceException e) {
+            LOGGER.error("Failed to query all instance IDs.", e);
+        } catch (Exception e) {
+            LOGGER.error("Unexpected error when querying all instance IDs.", e);
+        }
+
+        return instanceIds;
+    }
+
+    private static String getBackendList(Map<String, String> respHeaderMap) {
+        return respHeaderMap.entrySet().stream().filter(entry -> BACKEND_LIST_HEADER.equalsIgnoreCase(entry.getKey()))
+            .findAny().map(Map.Entry::getValue).orElse("");
+    }
+
+    /**
+     * 查询当前实例ID
+     *
+     * @return 当前实例ID
+     */
+    public static Optional<Integer> queryCurrentInstanceId() {
+        try {
+            // 通过环境变量获取当前实例名称
+            String podName = EnvUtil.getEnv(POD_NAME_ENV);
+            LOGGER.info("Start to query current pop name {} instance ID.", podName);
+            if (StringUtil.isEmpty(podName)) {
+                LOGGER.warn("POD_NAME environment variable is not set.");
+                return Optional.empty();
+            }
+
+            // 解析实例ID
+            Optional<Integer> instanceId = parseInstanceId(podName);
+            instanceId.ifPresent(
+                instance -> LOGGER.info("Query current instance ID successfully, instance ID: {}", instance));
+            return instanceId;
+        } catch (Exception e) {
+            LOGGER.error("Failed to query current instance ID.", e);
+            return Optional.empty();
+        }
+    }
+
+    /**
+     * 解析实例名称获取实例ID
+     *
+     * @param instanceName 实例名称
+     * @return 实例ID
+     */
+    private static Optional<Integer> parseInstanceId(String instanceName) {
+        if (StringUtil.isEmpty(instanceName)) {
+            return Optional.empty();
+        }
+
+        try {
+            // 按照"-"拆分实例名称，取最后的部分作为ID
+            String[] parts = instanceName.split(INSTANCE_NAME_SEPARATOR);
+            if (parts.length > 0) {
+                return Optional.of(Integer.parseInt(parts[parts.length - 1]));
+            }
+        } catch (NumberFormatException e) {
+            LOGGER.error("Failed to parse instance ID from instance name: {}", instanceName, e);
+        }
+
+        return Optional.empty();
+    }
+}
