+/*
+ * Copyright (c) Huawei Technologies Co., Ltd. 2025-2025. All rights reserved.
+ */
+
+package com.huawei.oss.wireless.experienceassuranceservice.common.impl.utils;
+
+import com.huawei.bsp.remoteservice.exception.ServiceException;
+import com.huawei.bsp.roa.util.restclient.RestfulResponse;
+import com.huawei.cloudsop.mockito.adapter.PowerMockRunnerJava21;
+import com.huawei.maos.commons.deploy.EnvUtil;
+import com.huawei.oss.rest.util.RestCaller;
+
+import org.junit.Assert;
+import org.junit.Before;
+import org.junit.Test;
+import org.junit.runner.RunWith;
+import org.mockito.Mockito;
+import org.powermock.api.mockito.PowerMockito;
+import org.powermock.core.classloader.annotations.PowerMockIgnore;
+import org.powermock.core.classloader.annotations.PrepareForTest;
+import org.powermock.reflect.Whitebox;
+
+import java.util.HashMap;
+import java.util.List;
+import java.util.Map;
+import java.util.Optional;
+
+@RunWith(PowerMockRunnerJava21.class)
+@PowerMockIgnore({"javax.management.*", "jdk.internal.reflect.*"})
+@PrepareForTest({InstanceUtils.class, RestCaller.class, EnvUtil.class})
+public class InstanceUtilsTest {
+    private RestCaller.Builder restCallerBuilder;
+
+    private RestCaller restCaller;
+
+    private RestfulResponse response;
+
+    @Before
+    public void setUp() throws Exception {
+        restCallerBuilder = Mockito.mock(RestCaller.Builder.class);
+        restCaller = Mockito.mock(RestCaller.class);
+        response = Mockito.mock(RestfulResponse.class);
+        PowerMockito.mockStatic(RestCaller.class);
+        PowerMockito.whenNew(RestCaller.Builder.class).withAnyArguments().thenReturn(restCallerBuilder);
+        PowerMockito.when(restCallerBuilder.header(Mockito.anyString(), Mockito.anyString())).thenReturn(restCallerBuilder);
+        PowerMockito.when(restCallerBuilder.build()).thenReturn(restCaller);
+        PowerMockito.when(restCaller.call()).thenReturn(response);
+        PowerMockito.mockStatic(EnvUtil.class);
+    }
+
+    @Test
+    public void testQueryAllInstanceIdsWhenNormalThenReturnInstanceIds() throws ServiceException {
+        // 准备测试数据
+        Map<String, String> respHeaderMap = Map.of("Xx-Backend-List", "all=service-b-1,service-b-2,service-b-3");
+
+        // 设置mock行为
+        PowerMockito.when(response.getRespHeaderMap()).thenReturn(respHeaderMap);
+
+        // 执行测试
+        List<Integer> result = InstanceUtils.queryAllInstanceIds();
+
+        // 验证结果
+        Assert.assertNotNull(result);
+        Assert.assertEquals(3, result.size());
+        Assert.assertTrue(result.contains(1));
+        Assert.assertTrue(result.contains(2));
+        Assert.assertTrue(result.contains(3));
+    }
+
+    @Test
+    public void testQueryAllInstanceIdsWhenEmptyResponseThenReturnEmptyList() throws ServiceException {
+        // 准备测试数据
+        Map<String, String> respHeaderMap = Map.of();
+
+        // 设置mock行为
+        PowerMockito.when(response.getRespHeaderMap()).thenReturn(respHeaderMap);
+
+        // 执行测试
+        List<Integer> result = InstanceUtils.queryAllInstanceIds();
+
+        // 验证结果
+        Assert.assertNotNull(result);
+        Assert.assertTrue(result.isEmpty());
+    }
+
+    @Test
+    public void testQueryAllInstanceIdsWhenInvalidResponseThenReturnEmptyList() throws ServiceException {
+        // 准备测试数据
+        Map<String, String> respHeaderMap = Map.of("Xx-Backend-List", "invalid=response");
+
+        // 设置mock行为
+        PowerMockito.when(response.getRespHeaderMap()).thenReturn(respHeaderMap);
+
+        // 执行测试
+        List<Integer> result = InstanceUtils.queryAllInstanceIds();
+
+        // 验证结果
+        Assert.assertNotNull(result);
+        Assert.assertTrue(result.isEmpty());
+    }
+
+    @Test
+    public void testQueryAllInstanceIdsWhenServiceExceptionThenReturnEmptyList() throws ServiceException {
+        // 设置mock行为
+        PowerMockito.when(restCaller.call()).thenThrow(new ServiceException());
+
+        // 执行测试
+        List<Integer> result = InstanceUtils.queryAllInstanceIds();
+
+        // 验证结果
+        Assert.assertNotNull(result);
+        Assert.assertTrue(result.isEmpty());
+    }
+
+    @Test
+    public void testQueryCurrentInstanceIdWhenNormalThenReturnInstanceId() {
+        // 设置mock行为
+        PowerMockito.when(EnvUtil.getEnv("POD_NAME")).thenReturn("service-b-10");
+
+        // 执行测试
+        Optional<Integer> result = InstanceUtils.queryCurrentInstanceId();
+
+        // 验证结果
+        Assert.assertTrue(result.isPresent());
+        Assert.assertEquals(Integer.valueOf(10), result.get());
+    }
+
+    @Test
+    public void testQueryCurrentInstanceIdWhenEnvNotSetThenReturnNull() {
+        // 设置mock行为
+        PowerMockito.when(EnvUtil.getEnv("POD_NAME")).thenReturn(null);
+
+        // 执行测试
+        Optional<Integer> result = InstanceUtils.queryCurrentInstanceId();
+
+        // 验证结果
+        Assert.assertFalse(result.isPresent());
+    }
+
+    @Test
+    public void testQueryCurrentInstanceIdWhenEnvEmptyThenReturnNull() {
+        // 设置mock行为
+        PowerMockito.when(EnvUtil.getEnv("POD_NAME")).thenReturn("");
+
+        // 执行测试
+        Optional<Integer> result = InstanceUtils.queryCurrentInstanceId();
+
+        // 验证结果
+        Assert.assertFalse(result.isPresent());
+    }
+
+    @Test
+    public void testQueryCurrentInstanceIdWhenInvalidFormatThenReturnNull() {
+        // 设置mock行为
+        PowerMockito.when(EnvUtil.getEnv("POD_NAME")).thenReturn("invalid-format");
+
+        // 执行测试
+        Optional<Integer> result = InstanceUtils.queryCurrentInstanceId();
+
+        // 验证结果
+        Assert.assertFalse(result.isPresent());
+    }
+
+    @Test
+    public void testQueryAllInstanceIdsWhenUnexpectedExceptionThenReturnEmptyList() throws Exception {
+        // 设置mock行为，模拟RestCaller.Builder构造函数抛出RuntimeException
+        PowerMockito.whenNew(RestCaller.Builder.class).withAnyArguments().thenThrow(new RuntimeException("Unexpected error"));
+
+        // 执行测试
+        List<Integer> result = InstanceUtils.queryAllInstanceIds();
+
+        // 验证结果
+        Assert.assertNotNull(result);
+        Assert.assertTrue(result.isEmpty());
+    }
+
+    @Test
+    public void testQueryAllInstanceIdsWhenInstanceNameInvalidFormatThenSkipInvalidInstance() throws ServiceException {
+        // 准备测试数据，其中包含一个无效格式的实例名称
+        Map<String, String> respHeaderMap = Map.of("Xx-Backend-List", "all=service-b-1,service-b-2,invalid-format");
+
+        // 设置mock行为
+        PowerMockito.when(response.getRespHeaderMap()).thenReturn(respHeaderMap);
+
+        // 执行测试
+        List<Integer> result = InstanceUtils.queryAllInstanceIds();
+
+        // 验证结果，应该只包含有效格式的实例ID
+        Assert.assertNotNull(result);
+        Assert.assertEquals(2, result.size());
+        Assert.assertTrue(result.contains(1));
+        Assert.assertTrue(result.contains(2));
+    }
+
+    @Test
+    public void testQueryCurrentInstanceIdWhenInstanceNameInvalidFormatThenReturnNull() {
+        // 设置mock行为，模拟环境变量返回无效格式的实例名称
+        PowerMockito.when(EnvUtil.getEnv("POD_NAME")).thenReturn("invalid-format");
+
+        // 执行测试
+        Optional<Integer> result = InstanceUtils.queryCurrentInstanceId();
+
+        // 验证结果
+        Assert.assertFalse(result.isPresent());
+    }
+
+    @Test
+    public void testQueryAllInstanceIdsWhenBackendListIsNullThenReturnEmptyList() throws ServiceException {
+        // 准备测试数据，backendList为null
+        Map<String, String> respHeaderMap = new HashMap<>();
+        respHeaderMap.put("Xx-Backend-List", null);
+
+        // 设置mock行为
+        PowerMockito.when(response.getRespHeaderMap()).thenReturn(respHeaderMap);
+
+        // 执行测试
+        List<Integer> result = InstanceUtils.queryAllInstanceIds();
+
+        // 验证结果
+        Assert.assertNotNull(result);
+        Assert.assertTrue(result.isEmpty());
+    }
+
+    @Test
+    public void testQueryAllInstanceIdsWhenBackendListNotStartWithAllThenReturnEmptyList() throws ServiceException {
+        // 准备测试数据，backendList不以"all="开头
+        Map<String, String> respHeaderMap = Map.of("Xx-Backend-List", "invalid=response");
+
+        // 设置mock行为
+        PowerMockito.when(response.getRespHeaderMap()).thenReturn(respHeaderMap);
+
+        // 执行测试
+        List<Integer> result = InstanceUtils.queryAllInstanceIds();
+
+        // 验证结果
+        Assert.assertNotNull(result);
+        Assert.assertTrue(result.isEmpty());
+    }
+
+    @Test
+    public void testQueryAllInstanceIdsWhenInstancesContainEmptyStringThenSkipEmptyInstance() throws ServiceException {
+        // 准备测试数据，instances数组包含空字符串
+        Map<String, String> respHeaderMap = Map.of("Xx-Backend-List", "all=service-b-1,,service-b-2");
+
+        // 设置mock行为
+        PowerMockito.when(response.getRespHeaderMap()).thenReturn(respHeaderMap);
+
+        // 执行测试
+        List<Integer> result = InstanceUtils.queryAllInstanceIds();
+
+        // 验证结果，应该只包含有效格式的实例ID
+        Assert.assertNotNull(result);
+        Assert.assertEquals(2, result.size());
+        Assert.assertTrue(result.contains(1));
+        Assert.assertTrue(result.contains(2));
+    }
+
+    @Test
+    public void testParseInstanceIdWhenInstanceNameEndsWithNonNumericThenReturnNull() throws Exception {
+        // 使用Whitebox调用私有方法parseInstanceId
+        Optional<Integer> result = Whitebox.invokeMethod(InstanceUtils.class, "parseInstanceId", "service-b-invalid");
+
+        // 验证结果
+        Assert.assertFalse(result.isPresent());
+    }
+
+    @Test
+    public void testParseInstanceIdWhenInstanceNameWithEmptyPartsThenReturnNull() throws Exception {
+        // 使用Whitebox调用私有方法parseInstanceId
+        Optional<Integer> result = Whitebox.invokeMethod(InstanceUtils.class, "parseInstanceId", "-");
+
+        // 验证结果
+        Assert.assertFalse(result.isPresent());
+    }
+}
